        { q: "Which <i>Taenia</i> species is found in cows?", a: "<i>Taenia saginata</i>" },
        { q: "Which <i>Taenia</i> species is found in pigs?", a: "<i>Taenia solium</i>" },
        { q: "Picture 5. Identify.", a: "<i>Taenia saginata</i><br>\"Common cow\" - no crown", img: "cards/hel/hel_101.jpg" },
        { q: "Picture 6. Identify.", a: "<i>Taenia solium</i><br>\"Royal pig\" - has a lil crown", img: "cards/hel/hel_102.jpg" },
        { q: "What is cystercercosis?", a: "Humans become an accidental intermediate host of <i>Taenia</i>, ingest eggs instead of larvae. The larvae can form encysts in human muscles, eyes, brains, etc." }
